    function openWorldOverlay3D(url, title) {
      var old = document.querySelector('.mn-world-3d-overlay');
      if (old) old.remove();
      var ov = document.createElement('div');
      ov.className = 'mn-world-3d-overlay';
      ov.style.cssText = 'position:fixed;inset:0;z-index:2147483640;background:#000;display:flex;width:100vw;height:100vh;overflow:hidden;';
      ov.innerHTML = '<iframe src="' + url + '" title="' + (title || 'Minest 3D World') + '" style="width:100%;height:100%;border:none;display:block;" allow="fullscreen; autoplay; gyroscope; accelerometer; xr-spatial-tracking"></iframe>' +
        '<button type="button" onclick="window.closeWorldOverlay3D()" class="mn-back-myworld-btn" aria-label="回到 My World" style="position:fixed;left:calc(14px + env(safe-area-inset-left));top:calc(12px + env(safe-area-inset-top));z-index:2147483647;paddin
          '<span style="font-size:16px;">‹</span> <b>回到 My World (小岛)</b>' +
        '</button>';
      ov.querySelector('.mn-back-myworld-btn').addEventListener('click', function (e) {
        e.preventDefault(); e.stopPropagation();
        ov.remove();
        if (window.hap) try { hap(); } catch (x) {}
      });
      window.addEventListener('message', function onMsg(e) {
        if (e.data && e.data.action === 'closeMinest3DOverlay') {
          window.removeEventListener('message', onMsg);
          ov.remove();
          if (window.hap) try { hap(); } catch (x) {}
        }
      });
      ['pointerdown', 'touchstart', 'keydown', 'wheel'].forEach(function (t) { ov.addEventListener(t, function (e) { e.stopPropagation(); }, { passive: true }); });
      document.body.appendChild(ov);
      var fr = ov.querySelector('iframe');
      setTimeout(function () { try { fr.focus(); } catch (x) {} }, 300);
    }
